CREATE OR REPLACE FUNCTION public.can_user_access_cliente(_cliente_id uuid)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $function$
DECLARE
    v_user_id uuid := auth.uid();
    v_is_admin boolean;
    v_is_gestor boolean;
    v_is_adm_sys boolean;
    v_is_financeiro boolean;
    v_is_consultor boolean;
    v_is_tecnico boolean;
    v_is_cliente boolean;
    v_is_b2b boolean;
    v_is_b2b_tec boolean;
    v_partner_id uuid;
BEGIN
    IF v_user_id IS NULL OR _cliente_id IS NULL THEN
        RETURN FALSE;
    END IF;

    v_is_admin := has_role(v_user_id, 'administrador'::app_role);
    v_is_gestor := has_role(v_user_id, 'gestor'::app_role);
    v_is_adm_sys := has_role(v_user_id, 'administrativo'::app_role);
    v_is_financeiro := has_role(v_user_id, 'financeiro'::app_role);
    v_is_consultor := has_role(v_user_id, 'consultor_tecnico'::app_role);
    v_is_tecnico := has_role(v_user_id, 'tecnico_agronomo'::app_role);
    v_is_cliente := has_role(v_user_id, 'cliente_produtor'::app_role);
    v_is_b2b := has_role(v_user_id, 'parceiro_b2b'::app_role);
    v_is_b2b_tec := has_role(v_user_id, 'parceiro_b2b_tecnico'::app_role);

    IF v_is_admin OR v_is_gestor OR v_is_adm_sys OR v_is_financeiro THEN
        RETURN TRUE;
    END IF;

    IF v_is_cliente THEN
        RETURN _cliente_id = ANY(get_cliente_ids_for_user(v_user_id));
    END IF;

    IF v_is_consultor OR v_is_tecnico THEN
        RETURN EXISTS (
            SELECT 1 FROM user_clientes uc
            WHERE uc.user_id = v_user_id AND uc.cliente_id = _cliente_id
        );
    END IF;

    IF v_is_b2b_tec THEN
        v_partner_id := public.get_user_partner_id();
        RETURN EXISTS (
            SELECT 1 FROM public.partner_technician_clients ptc
            WHERE ptc.cliente_id = _cliente_id
              AND ptc.technician_user_id = v_user_id
              AND ptc.partner_id = v_partner_id
              AND ptc.active = true
        );
    END IF;

    IF v_is_b2b THEN
        v_partner_id := public.get_user_partner_id();
        RETURN EXISTS (
            SELECT 1 FROM public.partner_technician_clients ptc
            WHERE ptc.cliente_id = _cliente_id
              AND ptc.partner_id = v_partner_id
              AND ptc.active = true
        );
    END IF;

    RETURN FALSE;
END;
$function$;

CREATE OR REPLACE FUNCTION public.convert_partner_simulation_to_order_secure(
  p_simulation_id uuid,
  p_observacoes text DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean;
  v_is_partner_b2b boolean;
  v_is_tecnico boolean;
  v_user_partner uuid;
  v_sim record;
  v_partner_id uuid;
  v_partner_desconto numeric(5,2);
  v_order_id uuid;
  v_numero text;
  v_item record;
  v_prod_row record;
  v_micro_row record;
  v_price record;
  v_nome text;
  v_codigo text;
  v_base numeric(12,2);
  v_dose_base numeric(12,2);
  v_preco_tabela numeric(12,2);
  v_desc numeric(5,2);
  v_preco_final numeric(12,2);
  v_line_subtotal numeric(12,2);
  v_subtotal numeric(12,2) := 0;
  v_total numeric(12,2) := 0;
  v_desconto_total numeric(12,2) := 0;
  v_items_count int := 0;
  v_qty numeric(12,2);
  v_unidade text := 'hectare';
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'auth_required';
  END IF;

  v_is_admin := has_role(v_uid, 'administrador') OR has_role(v_uid, 'gestor_comercial');
  v_is_partner_b2b := has_role(v_uid, 'parceiro_b2b');
  v_is_tecnico := has_role(v_uid, 'parceiro_b2b_tecnico');

  IF v_is_tecnico AND NOT v_is_admin AND NOT v_is_partner_b2b THEN
    RAISE EXCEPTION 'forbidden_role_tecnico_cannot_convert';
  END IF;

  IF NOT (v_is_admin OR v_is_partner_b2b) THEN
    RAISE EXCEPTION 'forbidden_role';
  END IF;

  SELECT * INTO v_sim
  FROM public.partner_simulations
  WHERE id = p_simulation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'simulation_not_found';
  END IF;

  v_partner_id := v_sim.partner_id;

  IF v_is_partner_b2b AND NOT v_is_admin THEN
    v_user_partner := public.get_user_partner_id();
    IF v_user_partner IS NULL OR v_user_partner <> v_partner_id THEN
      RAISE EXCEPTION 'forbidden_partner';
    END IF;
  END IF;

  IF v_sim.status IN ('convertida_pedido', 'arquivada') THEN
    RAISE EXCEPTION 'simulation_status_blocks_conversion:%', v_sim.status;
  END IF;

  IF v_sim.status NOT IN ('rascunho', 'enviada_gestor') THEN
    RAISE EXCEPTION 'simulation_status_invalid:%', v_sim.status;
  END IF;

  IF v_sim.cliente_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.partner_clients
      WHERE partner_id = v_partner_id
        AND cliente_id = v_sim.cliente_id
        AND active = true
    ) THEN
      RAISE EXCEPTION 'cliente_not_linked_to_partner';
    END IF;
  END IF;

  SELECT desconto_padrao INTO v_partner_desconto
  FROM public.partner_accounts
  WHERE id = v_partner_id AND ativo = true;
  IF v_partner_desconto IS NULL THEN
    RAISE EXCEPTION 'partner_not_found';
  END IF;

  INSERT INTO public.partner_orders (
    partner_id, cliente_id, created_by, status,
    subtotal, desconto_total, total,
    observacoes, cultura, area_total_ha, origin_simulation_id,
    partner_notes, ready_for_production
  ) VALUES (
    v_partner_id, v_sim.cliente_id, v_uid, 'em_analise_comercial',
    0, 0, 0,
    COALESCE(NULLIF(p_observacoes, ''), v_sim.observacoes),
    v_sim.cultura, v_sim.area_total_ha, p_simulation_id,
    NULLIF(p_observacoes, ''), false
  )
  RETURNING id, numero INTO v_order_id, v_numero;

  FOR v_item IN
    SELECT item_tipo, item_id, nome, quantidade
    FROM public.partner_simulation_items
    WHERE simulation_id = p_simulation_id
  LOOP
    v_qty := COALESCE(v_item.quantidade, 0);
    IF v_qty <= 0 THEN RAISE EXCEPTION 'invalid_qty'; END IF;

    v_base := NULL;
    v_dose_base := NULL;
    v_price := NULL;

    IF v_item.item_tipo = 'produto' THEN
      SELECT id, nome, codigo, valor_ha_brl, valor_dose_brl, valor_litro_brl, dose_ml_ha,
             ativo, COALESCE(b2b_enabled, true) AS b2b_enabled
        INTO v_prod_row FROM public.produtos WHERE id = v_item.item_id;
      IF NOT FOUND OR v_prod_row.ativo = false OR v_prod_row.b2b_enabled = false THEN
        RAISE EXCEPTION 'product_unavailable';
      END IF;
      v_nome := v_prod_row.nome;
      v_codigo := v_prod_row.codigo;

      v_dose_base := COALESCE(
        NULLIF(v_prod_row.valor_dose_brl, 0),
        NULLIF(v_prod_row.valor_litro_brl, 0) / 10.0
      );
      v_base := COALESCE(
        NULLIF(v_prod_row.valor_ha_brl, 0),
        CASE WHEN v_prod_row.dose_ml_ha IS NOT NULL AND v_prod_row.dose_ml_ha > 0
             THEN (v_prod_row.dose_ml_ha / 100.0) * v_dose_base END
      );

      SELECT preco_tabela, desconto_percentual, preco_final INTO v_price
      FROM public.partner_product_prices
      WHERE partner_id = v_partner_id AND product_id = v_item.item_id AND ativo = true;

    ELSIF v_item.item_tipo = 'microrganismo' THEN
      SELECT id, nome, codigo, valor_dose_brl, valor_litro_brl, dose_ml_ha,
             ativo, COALESCE(b2b_enabled, false) AS b2b_enabled
        INTO v_micro_row FROM public.microrganismos WHERE id = v_item.item_id;
      IF NOT FOUND OR v_micro_row.ativo = false OR v_micro_row.b2b_enabled = false THEN
        RAISE EXCEPTION 'product_unavailable';
      END IF;
      v_nome := v_micro_row.nome;
      v_codigo := v_micro_row.codigo;

      v_dose_base := COALESCE(
        NULLIF(v_micro_row.valor_dose_brl, 0),
        NULLIF(v_micro_row.valor_litro_brl, 0) / 10.0
      );
      v_base := CASE
        WHEN v_micro_row.dose_ml_ha IS NOT NULL AND v_micro_row.dose_ml_ha > 0
        THEN (v_micro_row.dose_ml_ha / 100.0) * v_dose_base
      END;

      SELECT preco_tabela, desconto_percentual, preco_final INTO v_price
      FROM public.partner_product_prices
      WHERE partner_id = v_partner_id AND microrganismo_id = v_item.item_id AND ativo = true;
    ELSE
      RAISE EXCEPTION 'invalid_item_tipo';
    END IF;

    IF v_price.preco_tabela IS NOT NULL THEN
      v_preco_tabela := v_price.preco_tabela;
      v_desc := COALESCE(v_price.desconto_percentual, 0);
      v_preco_final := COALESCE(v_price.preco_final, ROUND(v_preco_tabela * (1 - v_desc/100.0), 2));
    ELSE
      IF v_base IS NULL OR v_base <= 0 THEN
        RAISE EXCEPTION 'price_unavailable';
      END IF;
      v_preco_tabela := ROUND(v_base, 2);
      v_desc := COALESCE(v_partner_desconto, 0);
      v_preco_final := ROUND(v_preco_tabela * (1 - v_desc/100.0), 2);
    END IF;

    IF v_preco_final IS NULL OR v_preco_final <= 0 THEN
      RAISE EXCEPTION 'price_unavailable';
    END IF;

    v_line_subtotal := ROUND(v_preco_final * v_qty, 2);
    v_subtotal := v_subtotal + ROUND(v_preco_tabela * v_qty, 2);
    v_total := v_total + v_line_subtotal;

    INSERT INTO public.partner_order_items(
      order_id, product_id, microrganismo_id, quantidade, preco_unitario,
      desconto_percentual, subtotal, unidade_medida,
      produto_nome_snapshot, produto_codigo_snapshot,
      preco_tabela_snapshot, desconto_percentual_snapshot, preco_unitario_final_snapshot
    ) VALUES (
      v_order_id,
      CASE WHEN v_item.item_tipo = 'produto' THEN v_item.item_id END,
      CASE WHEN v_item.item_tipo = 'microrganismo' THEN v_item.item_id END,
      v_qty, v_preco_final, v_desc, v_line_subtotal, v_unidade,
      COALESCE(v_nome, v_item.nome), v_codigo,
      v_preco_tabela, v_desc, v_preco_final
    );

    v_items_count := v_items_count + 1;
  END LOOP;

  IF v_items_count = 0 THEN
    RAISE EXCEPTION 'empty_simulation';
  END IF;

  v_desconto_total := v_subtotal - v_total;

  UPDATE public.partner_orders
     SET subtotal = v_subtotal,
         desconto_total = v_desconto_total,
         total = v_total
   WHERE id = v_order_id;

  UPDATE public.partner_simulations
     SET status = 'convertida_pedido',
         converted_order_id = v_order_id,
         converted_by = v_uid,
         converted_at = now(),
         updated_at = now()
   WHERE id = p_simulation_id;

  INSERT INTO public.partner_order_audit_logs(
    order_id, partner_id, usuario_id, acao, dados_anteriores, dados_novos
  ) VALUES (
    v_order_id, v_partner_id, v_uid, 'converted_from_simulation', NULL,
    jsonb_build_object(
      'simulation_id', p_simulation_id,
      'cliente_id', v_sim.cliente_id,
      'subtotal', v_subtotal,
      'desconto_total', v_desconto_total,
      'total', v_total,
      'items_count', v_items_count
    )
  );

  RETURN v_order_id;
END;
$function$;

-- 1) Ajustar RPC: gestor B2B não cria mais partner_clients automaticamente
CREATE OR REPLACE FUNCTION public.assign_b2b_user_client_secure(
  p_user_id uuid,
  p_cliente_id uuid,
  p_assignment_type text DEFAULT 'monitoramento',
  p_can_create_simulation boolean DEFAULT true,
  p_can_monitor boolean DEFAULT true,
  p_notes text DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_partner uuid;
  v_id uuid;
  v_is_gest boolean := has_role(v_uid, 'parceiro_b2b'::app_role);
  v_is_admin boolean := has_role(v_uid, 'administrador'::app_role) OR has_role(v_uid, 'gestor_comercial'::app_role);
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;
  IF has_role(v_uid,'parceiro_b2b_tecnico'::app_role) THEN RAISE EXCEPTION 'access denied'; END IF;
  IF NOT (v_is_gest OR v_is_admin) THEN RAISE EXCEPTION 'access denied'; END IF;

  IF v_is_gest AND NOT v_is_admin THEN
    v_partner := get_user_partner_id();
  ELSE
    SELECT partner_id INTO v_partner FROM public.partner_users WHERE user_id = p_user_id LIMIT 1;
  END IF;

  IF v_partner IS NULL THEN RAISE EXCEPTION 'partner nao identificado'; END IF;

  IF v_is_admin THEN
    -- Admin/gestor comercial pode liberar cliente ao parceiro
    INSERT INTO public.partner_clients (partner_id, cliente_id, assigned_by, active)
    VALUES (v_partner, p_cliente_id, v_uid, true)
    ON CONFLICT (partner_id, cliente_id) DO UPDATE SET active = true, updated_at = now();
  ELSE
    -- Gestor B2B: exige liberação prévia
    IF NOT EXISTS (
      SELECT 1 FROM public.partner_clients
      WHERE partner_id = v_partner
        AND cliente_id = p_cliente_id
        AND active = true
    ) THEN
      RAISE EXCEPTION 'Cliente não está liberado para este parceiro. Solicite ao administrador AR Bio.';
    END IF;
  END IF;

  INSERT INTO public.partner_user_clients
    (partner_id, user_id, cliente_id, assignment_type, can_create_simulation, can_monitor, notes, assigned_by, active)
  VALUES
    (v_partner, p_user_id, p_cliente_id, p_assignment_type, p_can_create_simulation, p_can_monitor, p_notes, v_uid, true)
  ON CONFLICT (partner_id, user_id, cliente_id) DO UPDATE
    SET assignment_type = EXCLUDED.assignment_type,
        can_create_simulation = EXCLUDED.can_create_simulation,
        can_monitor = EXCLUDED.can_monitor,
        notes = EXCLUDED.notes,
        active = true,
        updated_at = now()
  RETURNING id INTO v_id;

  INSERT INTO public.partner_catalog_access_logs(user_id, role, action, partner_id, cliente_id, target_user_id, details)
  VALUES (v_uid, (SELECT role::text FROM public.user_roles WHERE user_id = v_uid LIMIT 1),
          'b2b_user_client_assigned', v_partner, p_cliente_id, p_user_id,
          jsonb_build_object('assignment_type', p_assignment_type));

  RETURN v_id;
END;
$function$;

-- 2) Refazer RLS de partner_clients
DROP POLICY IF EXISTS pc_select ON public.partner_clients;
DROP POLICY IF EXISTS pc_insert ON public.partner_clients;
DROP POLICY IF EXISTS pc_update ON public.partner_clients;

-- SELECT: admin/gestor_comercial livre; gestor B2B vê seu parceiro; técnico só vê os que tem vínculo ativo em PUC
CREATE POLICY pc_select ON public.partner_clients
FOR SELECT
USING (
  has_role(auth.uid(), 'administrador'::app_role)
  OR has_role(auth.uid(), 'gestor_comercial'::app_role)
  OR (
    has_role(auth.uid(), 'parceiro_b2b'::app_role)
    AND partner_id = get_user_partner_id()
  )
  OR (
    has_role(auth.uid(), 'parceiro_b2b_tecnico'::app_role)
    AND EXISTS (
      SELECT 1 FROM public.partner_user_clients puc
      WHERE puc.partner_id = partner_clients.partner_id
        AND puc.cliente_id = partner_clients.cliente_id
        AND puc.user_id = auth.uid()
        AND puc.active = true
    )
  )
);

-- INSERT: apenas administrador / gestor_comercial
CREATE POLICY pc_insert ON public.partner_clients
FOR INSERT
WITH CHECK (
  has_role(auth.uid(), 'administrador'::app_role)
  OR has_role(auth.uid(), 'gestor_comercial'::app_role)
);

-- UPDATE: apenas administrador / gestor_comercial
CREATE POLICY pc_update ON public.partner_clients
FOR UPDATE
USING (
  has_role(auth.uid(), 'administrador'::app_role)
  OR has_role(auth.uid(), 'gestor_comercial'::app_role)
)
WITH CHECK (
  has_role(auth.uid(), 'administrador'::app_role)
  OR has_role(auth.uid(), 'gestor_comercial'::app_role)
);

CREATE OR REPLACE FUNCTION public.get_b2b_user_client_simulations_secure(p_cliente_id uuid)
RETURNS TABLE (
  id uuid,
  titulo text,
  status text,
  total_cheio numeric,
  created_at timestamptz,
  created_by uuid
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_partner uuid;
  v_is_admin boolean := has_role(v_uid,'administrador'::app_role) OR has_role(v_uid,'gestor_comercial'::app_role);
  v_is_gest boolean := has_role(v_uid,'parceiro_b2b'::app_role);
  v_is_tec boolean := has_role(v_uid,'parceiro_b2b_tecnico'::app_role);
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;
  IF NOT (v_is_admin OR v_is_gest OR v_is_tec) THEN RAISE EXCEPTION 'access denied'; END IF;

  IF v_is_admin THEN
    RETURN QUERY
      SELECT s.id, s.titulo, s.status::text, s.total_cheio, s.created_at, s.created_by
      FROM public.partner_simulations s
      WHERE s.cliente_id = p_cliente_id
      ORDER BY s.created_at DESC
      LIMIT 100;
    RETURN;
  END IF;

  v_partner := public.get_user_partner_id();
  IF v_partner IS NULL THEN RAISE EXCEPTION 'partner nao identificado'; END IF;

  -- Cliente precisa estar vinculado ao usuário
  IF NOT EXISTS (
    SELECT 1 FROM public.partner_user_clients
    WHERE partner_id = v_partner
      AND cliente_id = p_cliente_id
      AND user_id = v_uid
      AND active = true
  ) THEN
    RAISE EXCEPTION 'cliente nao vinculado';
  END IF;

  IF v_is_tec THEN
    RETURN QUERY
      SELECT s.id, s.titulo, s.status::text, s.total_cheio, s.created_at, s.created_by
      FROM public.partner_simulations s
      WHERE s.cliente_id = p_cliente_id
        AND s.partner_id = v_partner
        AND s.created_by = v_uid
      ORDER BY s.created_at DESC
      LIMIT 100;
  ELSE
    RETURN QUERY
      SELECT s.id, s.titulo, s.status::text, s.total_cheio, s.created_at, s.created_by
      FROM public.partner_simulations s
      WHERE s.cliente_id = p_cliente_id
        AND s.partner_id = v_partner
      ORDER BY s.created_at DESC
      LIMIT 100;
  END IF;
END;
$function$;

GRANT EXECUTE ON FUNCTION public.get_b2b_user_client_simulations_secure(uuid) TO authenticated;

CREATE OR REPLACE FUNCTION public.send_partner_simulation_to_manager_secure(p_simulation_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_sim partner_simulations%ROWTYPE;
  v_partner_id uuid;
  v_allowed boolean := false;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Não autenticado';
  END IF;

  SELECT * INTO v_sim FROM partner_simulations WHERE id = p_simulation_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Simulação não encontrada';
  END IF;

  IF v_sim.status <> 'rascunho' THEN
    RAISE EXCEPTION 'Somente simulações em rascunho podem ser enviadas';
  END IF;

  v_partner_id := get_user_partner_id();

  IF has_role(v_uid, 'administrador') OR has_role(v_uid, 'gestor_comercial') THEN
    v_allowed := true;
  ELSIF has_role(v_uid, 'parceiro_b2b_tecnico') AND v_sim.created_by = v_uid THEN
    v_allowed := true;
  ELSIF has_role(v_uid, 'parceiro_b2b') AND (v_sim.created_by = v_uid OR v_sim.partner_id = v_partner_id) THEN
    v_allowed := true;
  END IF;

  IF NOT v_allowed THEN
    RAISE EXCEPTION 'Sem permissão para enviar esta simulação';
  END IF;

  UPDATE partner_simulations
    SET status = 'enviada_gestor', updated_at = now()
    WHERE id = p_simulation_id;

  INSERT INTO partner_audit_logs (partner_id, usuario_id, acao, dados_anteriores, dados_novos)
  VALUES (
    v_sim.partner_id, v_uid, 'simulation_sent_to_manager',
    jsonb_build_object('simulation_id', p_simulation_id, 'status', v_sim.status),
    jsonb_build_object('simulation_id', p_simulation_id, 'status', 'enviada_gestor')
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.archive_partner_simulation_secure(p_simulation_id uuid, p_reason text DEFAULT NULL)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_sim partner_simulations%ROWTYPE;
  v_partner_id uuid;
  v_allowed boolean := false;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Não autenticado';
  END IF;

  SELECT * INTO v_sim FROM partner_simulations WHERE id = p_simulation_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Simulação não encontrada';
  END IF;

  IF v_sim.status = 'convertida_pedido' THEN
    RAISE EXCEPTION 'Simulação já convertida em pedido não pode ser arquivada';
  END IF;

  v_partner_id := get_user_partner_id();

  IF has_role(v_uid, 'administrador') OR has_role(v_uid, 'gestor_comercial') THEN
    v_allowed := true;
  ELSIF has_role(v_uid, 'parceiro_b2b_tecnico') AND v_sim.created_by = v_uid THEN
    v_allowed := true;
  ELSIF has_role(v_uid, 'parceiro_b2b') AND v_sim.partner_id = v_partner_id THEN
    v_allowed := true;
  END IF;

  IF NOT v_allowed THEN
    RAISE EXCEPTION 'Sem permissão para arquivar esta simulação';
  END IF;

  UPDATE partner_simulations
    SET status = 'arquivada', updated_at = now()
    WHERE id = p_simulation_id;

  INSERT INTO partner_audit_logs (partner_id, usuario_id, acao, dados_anteriores, dados_novos)
  VALUES (
    v_sim.partner_id, v_uid, 'simulation_archived',
    jsonb_build_object('simulation_id', p_simulation_id, 'status', v_sim.status),
    jsonb_build_object('simulation_id', p_simulation_id, 'status', 'arquivada', 'reason', p_reason)
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.send_partner_simulation_to_manager_secure(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.archive_partner_simulation_secure(uuid, text) TO authenticated;

CREATE OR REPLACE FUNCTION public.log_partner_catalog_access_secure(
  p_action text,
  p_item_tipo text DEFAULT NULL,
  p_item_id uuid DEFAULT NULL,
  p_cliente_id uuid DEFAULT NULL,
  p_simulation_id uuid DEFAULT NULL,
  p_order_id uuid DEFAULT NULL,
  p_target_user_id uuid DEFAULT NULL,
  p_details jsonb DEFAULT '{}'::jsonb,
  p_partner_id uuid DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_partner_id uuid;
  v_role text;
  v_log_id uuid;
  v_details jsonb;
  v_allowed_actions text[] := ARRAY[
    'b2b_user_client_assigned','b2b_user_client_unassigned','producer_view',
    'catalog_view','item_view','ficha_view','ficha_download',
    'simulation_created','simulation_sent_to_manager','simulation_archived',
    'simulation_converted_to_order'
  ];
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Não autenticado';
  END IF;

  IF NOT (p_action = ANY(v_allowed_actions)) THEN
    RAISE EXCEPTION 'Ação de log inválida: %', p_action;
  END IF;

  IF has_role(v_uid, 'administrador') THEN
    v_role := 'administrador';
    v_partner_id := p_partner_id;
  ELSIF has_role(v_uid, 'gestor_comercial') THEN
    v_role := 'gestor_comercial';
    v_partner_id := p_partner_id;
  ELSIF has_role(v_uid, 'parceiro_b2b') THEN
    v_role := 'parceiro_b2b';
    v_partner_id := get_user_partner_id();
  ELSIF has_role(v_uid, 'parceiro_b2b_tecnico') THEN
    v_role := 'parceiro_b2b_tecnico';
    v_partner_id := get_user_partner_id();
  ELSE
    RAISE EXCEPTION 'Sem permissão para registrar log B2B';
  END IF;

  v_details := COALESCE(p_details, '{}'::jsonb);
  IF p_item_tipo IS NOT NULL THEN
    v_details := v_details || jsonb_build_object('item_tipo', p_item_tipo);
  END IF;
  IF p_item_id IS NOT NULL THEN
    v_details := v_details || jsonb_build_object('item_id', p_item_id);
  END IF;

  INSERT INTO partner_catalog_access_logs (
    user_id, role, action, partner_id, cliente_id,
    simulation_id, order_id, target_user_id, details
  ) VALUES (
    v_uid, v_role, p_action, v_partner_id, p_cliente_id,
    p_simulation_id, p_order_id, p_target_user_id, v_details
  ) RETURNING id INTO v_log_id;

  RETURN v_log_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.log_partner_catalog_access_secure(text, text, uuid, uuid, uuid, uuid, uuid, jsonb, uuid) TO authenticated;

